'use strict';

const fs = require('node:fs');
const { TodoError } = require('./todos');

const TODO_FILE_NAME = 'todos.json';

const FIELD_RULES = [
  { field: 'id', expected: 'a positive integer', isValid: (value) => Number.isSafeInteger(value) && value > 0 },
  { field: 'text', expected: 'a non-empty string', isValid: (value) => typeof value === 'string' && value.trim() !== '' },
  { field: 'completed', expected: 'a boolean', isValid: (value) => typeof value === 'boolean' },
  {
    field: 'createdAt',
    expected: 'an ISO 8601 timestamp',
    isValid: (value) => typeof value === 'string' && !Number.isNaN(Date.parse(value)),
  },
];

function corrupted(filePath, detail) {
  return new TodoError(`${filePath} is corrupted: ${detail}. Fix or remove the file and try again.`);
}

function validateTodos(data, filePath) {
  if (!Array.isArray(data)) {
    throw corrupted(filePath, 'expected a JSON array of todos');
  }
  const seenIds = new Set();
  data.forEach((todo, index) => {
    if (todo === null || typeof todo !== 'object' || Array.isArray(todo)) {
      throw corrupted(filePath, `entry ${index} is not an object`);
    }
    for (const { field, expected, isValid } of FIELD_RULES) {
      if (!isValid(todo[field])) {
        throw corrupted(filePath, `entry ${index} has an invalid "${field}" (expected ${expected})`);
      }
    }
    if (seenIds.has(todo.id)) {
      throw corrupted(filePath, `id ${todo.id} appears more than once`);
    }
    seenIds.add(todo.id);
  });
}

/** Reads and validates the todo list. A missing file is an empty list. */
function loadTodos(filePath) {
  let raw;
  try {
    raw = fs.readFileSync(filePath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') {
      return [];
    }
    throw new TodoError(`Could not read ${filePath}: ${err.message}`, { cause: err });
  }

  let data;
  try {
    data = JSON.parse(raw);
  } catch (err) {
    throw corrupted(filePath, `invalid JSON (${err.message})`);
  }
  validateTodos(data, filePath);
  return data;
}

/**
 * Writes to a temporary file and renames it over the target, so a crash or a
 * concurrent writer never leaves a half-written todos.json behind.
 */
function saveTodos(filePath, todos) {
  const tempPath = `${filePath}.${process.pid}.tmp`;
  try {
    fs.writeFileSync(tempPath, `${JSON.stringify(todos, null, 2)}\n`);
    fs.renameSync(tempPath, filePath);
  } catch (err) {
    fs.rmSync(tempPath, { force: true });
    throw new TodoError(`Could not write ${filePath}: ${err.message}`, { cause: err });
  }
}

module.exports = {
  TODO_FILE_NAME,
  loadTodos,
  saveTodos,
};

