'use strict';

const { afterEach, beforeEach, describe, it } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { TODO_FILE_NAME, loadTodos, saveTodos } = require('../lib/store');

const CREATED_AT = '2026-01-02T03:04:05.000Z';

function makeTodo(id, overrides = {}) {
  return { id, text: `Todo ${id}`, completed: false, createdAt: CREATED_AT, ...overrides };
}

let dir;
let filePath;

beforeEach(() => {
  dir = fs.mkdtempSync(path.join(os.tmpdir(), 'todo-store-'));
  filePath = path.join(dir, TODO_FILE_NAME);
});

afterEach(() => {
  fs.rmSync(dir, { recursive: true, force: true });
});

describe('loadTodos', () => {
  it('returns an empty list when the file does not exist', () => {
    assert.deepEqual(loadTodos(filePath), []);
    assert.equal(fs.existsSync(filePath), false);
  });

  it('returns the todos stored in a valid file', () => {
    const todos = [makeTodo(1), makeTodo(3, { completed: true })];
    fs.writeFileSync(filePath, JSON.stringify(todos));
    assert.deepEqual(loadTodos(filePath), todos);
  });

  for (const [name, contents] of [
    ['truncated JSON', '[{"id": 1,'],
    ['an empty file', ''],
  ]) {
    it(`rejects ${name} and names the file`, () => {
      fs.writeFileSync(filePath, contents);
      assert.throws(() => loadTodos(filePath), {
        name: 'TodoError',
        message: (message) => message.includes(filePath) && /is corrupted: invalid JSON/.test(message),
      });
    });
  }

  const wrongShapes = [
    { name: 'a top-level object', data: { todos: [] }, message: /expected a JSON array of todos/ },
    { name: 'a null entry', data: [null], message: /entry 0 is not an object/ },
    { name: 'an array entry', data: [[1]], message: /entry 0 is not an object/ },
    { name: 'a string id', data: [makeTodo('1')], message: /entry 0 has an invalid "id"/ },
    { name: 'a zero id', data: [makeTodo(0)], message: /entry 0 has an invalid "id"/ },
    { name: 'a fractional id', data: [makeTodo(1), makeTodo(1.5)], message: /entry 1 has an invalid "id"/ },
    { name: 'missing text', data: [makeTodo(1, { text: undefined })], message: /invalid "text"/ },
    { name: 'blank text', data: [makeTodo(1, { text: '  ' })], message: /invalid "text"/ },
