'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const { TodoError, addTodo, completeTodo, deleteTodo, formatTodos, parseId } = require('../lib/todos');

const NOW = new Date('2026-01-02T03:04:05.000Z');

function makeTodo(id, overrides = {}) {
  return { id, text: `Todo ${id}`, completed: false, createdAt: NOW.toISOString(), ...overrides };
}

describe('parseId', () => {
  const valid = [
    ['1', 1],
    ['42', 42],
    ['007', 7],
    [String(Number.MAX_SAFE_INTEGER), Number.MAX_SAFE_INTEGER],
  ];
  for (const [raw, expected] of valid) {
    it(`parses "${raw}" as ${expected}`, () => {
      assert.equal(parseId(raw), expected);
    });
  }

  // Each of these is accepted by Number() or parseInt(), which is the bug this guards against.
  const invalid = ['', '0', '00', '-1', '+1', '1.5', '1e2', '0x1', ' 1', '1 ', '1abc', 'abc', 'Infinity', '9007199254740992', '١'];
  for (const raw of invalid) {
    it(`rejects ${JSON.stringify(raw)}`, () => {
      assert.throws(() => parseId(raw), { name: 'TodoError', message: /Invalid todo id/ });
    });
  }
});

describe('addTodo', () => {
  it('gives the first todo id 1, completed false and an ISO createdAt', () => {
    const { todos, todo } = addTodo([], 'Buy groceries', NOW);
    assert.deepEqual(todo, { id: 1, text: 'Buy groceries', completed: false, createdAt: '2026-01-02T03:04:05.000Z' });
    assert.deepEqual(todos, [todo]);
  });

  it('uses one more than the highest id, not the list length', () => {
    const { todo } = addTodo([makeTodo(2), makeTodo(5)], 'Next', NOW);
    assert.equal(todo.id, 6);
  });

  it('trims the text and collapses inner whitespace, including newlines', () => {
    const { todo } = addTodo([], '  Buy \n milk\t and   eggs  ', NOW);
    assert.equal(todo.text, 'Buy milk and eggs');
  });

  it('keeps unicode text intact', () => {
    const { todo } = addTodo([], 'Café ☕ 買い物 👩‍👩‍👧', NOW);
    assert.equal(todo.text, 'Café ☕ 買い物 👩‍👩‍👧');
  });

  for (const text of ['', '   ', '\n\t ']) {
    it(`rejects blank text ${JSON.stringify(text)}`, () => {
      assert.throws(() => addTodo([], text, NOW), { name: 'TodoError', message: /cannot be empty/ });
    });
  }

  it('does not modify the input list', () => {
    const todos = [makeTodo(1)];
    addTodo(todos, 'Another', NOW);
    assert.deepEqual(todos, [makeTodo(1)]);
  });
});

describe('completeTodo', () => {
  it('marks only the matching todo as done', () => {
    const { todos, todo, changed } = completeTodo([makeTodo(1), makeTodo(2)], 2);
    assert.equal(changed, true);
    assert.deepEqual(todo, makeTodo(2, { completed: true }));
    assert.deepEqual(todos, [makeTodo(1), makeTodo(2, { completed: true })]);
  });

  it('reports changed: false for a todo that is already done', () => {
    const input = [makeTodo(1, { completed: true })];
    const { todos, changed } = completeTodo(input, 1);
    assert.equal(changed, false);
    assert.deepEqual(todos, input);
  });

  it('throws a TodoError for an id that does not exist', () => {
    assert.throws(() => completeTodo([makeTodo(1)], 2), { name: 'TodoError', message: /No todo with id 2/ });
  });

  it('throws a TodoError on an empty list', () => {
    assert.throws(() => completeTodo([], 1), TodoError);
  });

  it('does not modify the input list or its todos', () => {
    const todos = [makeTodo(1)];
    completeTodo(todos, 1);
    assert.deepEqual(todos, [makeTodo(1)]);
  });
});

describe('deleteTodo', () => {
  it('removes only the matching todo and returns it', () => {
    const { todos, todo } = deleteTodo([makeTodo(1), makeTodo(2), makeTodo(3)], 2);
    assert.deepEqual(todo, makeTodo(2));
    assert.deepEqual(todos, [makeTodo(1), makeTodo(3)]);
  });

  it('throws a TodoError for an id that does not exist', () => {
    assert.throws(() => deleteTodo([makeTodo(1)], 3), { name: 'TodoError', message: /No todo with id 3/ });
  });

  it('does not modify the input list', () => {
    const todos = [makeTodo(1), makeTodo(2)];
    deleteTodo(todos, 1);
    assert.deepEqual(todos, [makeTodo(1), makeTodo(2)]);
  });
});

describe('formatTodos', () => {
  it('says there are no todos for an empty list', () => {
    assert.equal(formatTodos([]), 'No todos yet.');
  });

  it('shows the id, a [x] or [ ] status indicator and the text, then a summary', () => {
    const output = formatTodos([makeTodo(1, { text: 'Buy groceries' }), makeTodo(2, { text: 'Walk the dog', completed: true })]);
    assert.equal(output, ['1. [ ] Buy groceries', '2. [x] Walk the dog', '', '1 pending, 1 done'].join('\n'));
  });
});

