'use strict';

const { afterEach, beforeEach, describe, it } = require('node:test');
const assert = require('node:assert/strict');
const { spawn, spawnSync } = require('node:child_process');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { loadTodos } = require('../lib/store');

const INDEX = path.join(__dirname, '..', 'index.js');
const TIMEOUT_MS = 10_000;
const SEEDED_TODOS = 50_000;

let dir;

beforeEach(() => {
  dir = fs.mkdtempSync(path.join(os.tmpdir(), 'todo-e2e-'));
});

afterEach(() => {
  fs.rmSync(dir, { recursive: true, force: true });
});

function todo(...args) {
  const result = spawnSync(process.execPath, [INDEX, ...args], { cwd: dir, encoding: 'utf8', timeout: TIMEOUT_MS });
  return { status: result.status, stdout: result.stdout, stderr: result.stderr };
}

function todoAsync(...args) {
  return new Promise((resolve, reject) => {
    const child = spawn(process.execPath, [INDEX, ...args], {
      cwd: dir,
      stdio: ['ignore', 'ignore', 'pipe'],
      timeout: TIMEOUT_MS,
    });
    let stderr = '';
    child.stderr.on('data', (chunk) => {
      stderr += chunk;
    });
    child.on('error', reject);
    child.on('close', (status) => resolve({ status, stderr }));
  });
}

describe('node index.js', () => {
  it('adds, lists, completes and deletes todos in the current directory', () => {
    assert.deepEqual(todo('add', 'Buy groceries'), { status: 0, stdout: 'Added todo 1: Buy groceries\n', stderr: '' });
    assert.deepEqual(todo('add', 'Café ☕ 買い物'), { status: 0, stdout: 'Added todo 2: Café ☕ 買い物\n', stderr: '' });
    assert.deepEqual(todo('complete', '1'), { status: 0, stdout: 'Completed todo 1: Buy groceries\n', stderr: '' });
    assert.deepEqual(todo('list'), {
      status: 0,
      stdout: '1. [x] Buy groceries\n2. [ ] Café ☕ 買い物\n\n1 pending, 1 done\n',
      stderr: '',
    });

    const stored = JSON.parse(fs.readFileSync(path.join(dir, 'todos.json'), 'utf8'));
    assert.deepEqual(
      stored.map(({ id, text, completed }) => ({ id, text, completed })),
      [
        { id: 1, text: 'Buy groceries', completed: true },
        { id: 2, text: 'Café ☕ 買い物', completed: false },
      ],
    );
    for (const { createdAt } of stored) {
      assert.equal(new Date(createdAt).toISOString(), createdAt);
    }

    assert.deepEqual(todo('delete', '1'), { status: 0, stdout: 'Deleted todo 1: Buy groceries\n', stderr: '' });
    assert.deepEqual(todo('delete', '2'), { status: 0, stdout: 'Deleted todo 2: Café ☕ 買い物\n', stderr: '' });
    assert.deepEqual(todo('list'), { status: 0, stdout: 'No todos yet.\n', stderr: '' });
  });

  it('writes errors to stderr and exits with status 1', () => {
    const result = todo('complete', '42');
    assert.equal(result.status, 1);
    assert.equal(result.stdout, '');
    assert.match(result.stderr, /^Error: No todo with id 42\./);
  });

  it('prints usage to stderr and exits with status 1 when run without arguments', () => {
    const result = todo();
    assert.equal(result.status, 1);
    assert.match(result.stderr, /Usage: node index\.js <command>/);
  });

  it('never lets a reader see a half-written todos.json while other processes write', async () => {
    // A large file keeps each write slow enough that an in-place write would be seen half-done.
    const seeded = Array.from({ length: SEEDED_TODOS }, (_, i) => ({
      id: i + 1,
      text: `Seeded task ${i + 1}`,
      completed: false,
      createdAt: '2026-01-02T03:04:05.000Z',
    }));
    const file = path.join(dir, 'todos.json');
    fs.writeFileSync(file, JSON.stringify(seeded));

    let writersDone = false;
    const writers = Promise.all(Array.from({ length: 8 }, (_, i) => todoAsync('add', `Task ${i}`))).finally(() => {
      writersDone = true;
    });
    const partialReads = [];
    // Sequential on purpose: keep sampling the file until every writer has exited.
    while (!writersDone) {
      const raw = await fs.promises.readFile(file, 'utf8');
      try {
        JSON.parse(raw);
      } catch (err) {
        partialReads.push(`${raw.length} bytes: ${err.message}`);
      }
    }
    assert.deepEqual(partialReads, []);
    for (const result of await writers) {
      assert.deepEqual(result, { status: 0, stderr: '' });
    }

    // Without a lock, concurrent adds can overwrite each other, but the file must stay a complete list.
    const todos = loadTodos(file);
    assert.ok(todos.length > SEEDED_TODOS && todos.length <= SEEDED_TODOS + 8, `unexpected count ${todos.length}`);
    assert.deepEqual(fs.readdirSync(dir), ['todos.json']);
  });
});

