#!/usr/bin/env node
'use strict';

const path = require('node:path');
const { TodoError, addTodo, completeTodo, deleteTodo, formatTodos, parseId } = require('./lib/todos');
const { TODO_FILE_NAME, loadTodos, saveTodos } = require('./lib/store');

const USAGE = `Usage: node index.js <command> [arguments]

Commands:
  add <text>       Add a new todo
  list             List all todos
  complete <id>    Mark a todo as done
  delete <id>      Delete a todo
  help             Show this help`;

function idArgument(args, command) {
  if (args.length === 0) {
    throw new TodoError(`Missing todo id. Usage: node index.js ${command} <id>`);
  }
  if (args.length > 1) {
    throw new TodoError(`Too many arguments. Usage: node index.js ${command} <id>`);
  }
  return parseId(args[0]);
}

const COMMANDS = new Map([
  [
    'add',
    (args, filePath, now) => {
      if (args.length === 0) {
        throw new TodoError('Missing todo text. Usage: node index.js add "<text>"');
      }
      const { todos, todo } = addTodo(loadTodos(filePath), args.join(' '), now);
      saveTodos(filePath, todos);
      return `Added todo ${todo.id}: ${todo.text}`;
    },
  ],
  [
    'list',
    (args, filePath) => {
      if (args.length > 0) {
        throw new TodoError('The list command takes no arguments. Usage: node index.js list');
      }
      return formatTodos(loadTodos(filePath));
    },
  ],
  [
    'complete',
    (args, filePath) => {
      const id = idArgument(args, 'complete');
      const { todos, todo, changed } = completeTodo(loadTodos(filePath), id);
      if (!changed) {
        return `Todo ${id} is already done: ${todo.text}`;
      }
      saveTodos(filePath, todos);
      return `Completed todo ${id}: ${todo.text}`;
    },
  ],
  [
    'delete',
    (args, filePath) => {
      const id = idArgument(args, 'delete');
      const { todos, todo } = deleteTodo(loadTodos(filePath), id);
      saveTodos(filePath, todos);
      return `Deleted todo ${id}: ${todo.text}`;
    },
  ],
]);

const HELP_FLAGS = new Set(['help', '--help', '-h']);

/**
 * Runs one CLI invocation against `<cwd>/todos.json` and returns what to print
 * instead of printing it. User errors come back as exit code 1; anything else
 * is a bug and is re-thrown.
 */
function run(argv, { cwd = process.cwd(), now = new Date() } = {}) {
  const [command, ...args] = argv;
  if (command === undefined) {
    return { exitCode: 1, stdout: '', stderr: `Error: Missing command.\n\n${USAGE}` };
  }
  if (HELP_FLAGS.has(command)) {
    return { exitCode: 0, stdout: USAGE, stderr: '' };
  }
  const handler = COMMANDS.get(command);
  if (!handler) {
    return { exitCode: 1, stdout: '', stderr: `Error: Unknown command "${command}".\n\n${USAGE}` };
  }
  try {
    return { exitCode: 0, stdout: handler(args, path.join(cwd, TODO_FILE_NAME), now), stderr: '' };
  } catch (err) {
    if (err instanceof TodoError) {
      return { exitCode: 1, stdout: '', stderr: `Error: ${err.message}` };
    }
    throw err;
  }
}

if (require.main === module) {
  const { exitCode, stdout, stderr } = run(process.argv.slice(2));
  if (stdout) {
    process.stdout.write(`${stdout}\n`);
  }
  if (stderr) {
    process.stderr.write(`${stderr}\n`);
  }
  process.exitCode = exitCode;
}

module.exports = { run, USAGE };

